using ManufacturerERP.Data; using ManufacturerERP.Models; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace ManufacturerERP.Services;
public interface IProductionService { Task<string> NextNumberAsync(); Task PlanAsync(int id, ClaimsPrincipal user); Task StartAsync(int id, ClaimsPrincipal user); Task ConsumeAsync(int id, ClaimsPrincipal user); Task ConsumeAsync(int id, IReadOnlyDictionary<int, decimal> quantities, ClaimsPrincipal user); Task CompleteAsync(int id, decimal actualQuantity, decimal wastageQuantity, string? notes, ClaimsPrincipal user); }
public class ProductionService(ApplicationDbContext db, IAuditService audit) : IProductionService
{
    public Task<string> NextNumberAsync() => Task.FromResult($"PROD-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}");
    public async Task PlanAsync(int id,ClaimsPrincipal user){var order=await db.ProductionOrders.FindAsync(id)??throw new InvalidOperationException("Production order not found.");if(order.Status!=ProductionOrderStatus.Draft)throw new InvalidOperationException("Only draft orders can be planned.");order.Status=ProductionOrderStatus.Planned;order.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync(user,"Plan","ProductionOrder",id,$"Planned {order.Number}");}
    public async Task StartAsync(int id,ClaimsPrincipal user){var order=await db.ProductionOrders.FindAsync(id)??throw new InvalidOperationException("Production order not found.");if(order.Status!=ProductionOrderStatus.Planned)throw new InvalidOperationException("Only planned orders can be started.");order.Status=ProductionOrderStatus.InProgress;order.StartedAt=DateTime.UtcNow;order.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync(user,"Start","ProductionOrder",id,$"Started {order.Number}");}
    public Task ConsumeAsync(int id, ClaimsPrincipal user) => ConsumeAsync(id, new Dictionary<int, decimal>(), user);
    public async Task ConsumeAsync(int id, IReadOnlyDictionary<int, decimal> quantities, ClaimsPrincipal user){await using var tx=await db.Database.BeginTransactionAsync();var order=await db.ProductionOrders.Include(x=>x.Materials).ThenInclude(x=>x.Product).FirstOrDefaultAsync(x=>x.Id==id)??throw new InvalidOperationException("Production order not found.");if(order.Status!=ProductionOrderStatus.InProgress)throw new InvalidOperationException("Production must be in progress before material consumption.");if(quantities.Count==0)throw new InvalidOperationException("Enter at least one material quantity.");var posted=0;foreach(var material in order.Materials){if(!quantities.TryGetValue(material.Id,out var consumedQuantity))continue;posted++;if(await db.InventoryTransactions.AnyAsync(x=>x.ReferenceType=="ProductionOrder"&&x.ReferenceId==id&&x.TransactionType==InventoryTransactionType.ProductionConsumption&&x.ProductId==material.ProductId))throw new InvalidOperationException($"Material consumption has already been posted for {material.Product?.Name}.");if(consumedQuantity<=0)throw new InvalidOperationException($"Consumption quantity must be greater than zero for {material.Product?.Name}.");if(consumedQuantity>material.PlannedQuantity)throw new InvalidOperationException($"Consumption quantity cannot exceed planned quantity for {material.Product?.Name}.");if(material.Product?.ItemType is not (ItemType.RawMaterial or ItemType.Consumable))throw new InvalidOperationException("Only raw materials or consumables may be consumed.");var available=await db.InventoryTransactions.Where(x=>x.ProductId==material.ProductId&&x.WarehouseId==order.WarehouseId).SumAsync(x=>(decimal?)x.Quantity)??0;if(consumedQuantity>available)throw new InvalidOperationException($"Insufficient stock for {material.Product?.Name}. Required: {consumedQuantity}. Available: {available}.");var receivedQuantity=await db.InventoryTransactions.Where(x=>x.ProductId==material.ProductId&&x.WarehouseId==order.WarehouseId&&x.TransactionType==InventoryTransactionType.PurchaseReceipt).SumAsync(x=>(decimal?)x.Quantity)??0;var receivedValue=await db.InventoryTransactions.Where(x=>x.ProductId==material.ProductId&&x.WarehouseId==order.WarehouseId&&x.TransactionType==InventoryTransactionType.PurchaseReceipt).SumAsync(x=>(decimal?)(x.Quantity*x.UnitCost))??0;if(receivedQuantity>0)material.UnitCost=receivedValue/receivedQuantity;material.ConsumedQuantity=consumedQuantity;material.TotalCost=consumedQuantity*material.UnitCost;db.InventoryTransactions.Add(new InventoryTransaction{ProductId=material.ProductId,WarehouseId=order.WarehouseId,TransactionType=InventoryTransactionType.ProductionConsumption,Quantity=-consumedQuantity,UnitCost=material.UnitCost,ReferenceType="ProductionOrder",ReferenceId=id,TransactionDate=order.ProductionDate,Notes=material.Notes,CreatedById=user.FindFirstValue(ClaimTypes.NameIdentifier)});}if(posted==0)throw new InvalidOperationException("Select a production material.");order.MaterialCost=order.Materials.Sum(x=>x.TotalCost);order.TotalCost=order.MaterialCost;order.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync(user,"Consume","ProductionOrder",id,$"Posted material consumption for {order.Number}");await tx.CommitAsync();}
    public async Task CompleteAsync(int id,decimal actualQuantity,decimal wastageQuantity,string? notes,ClaimsPrincipal user){await using var tx=await db.Database.BeginTransactionAsync();var order=await db.ProductionOrders.FirstOrDefaultAsync(x=>x.Id==id)??throw new InvalidOperationException("Production order not found.");if(order.Status!=ProductionOrderStatus.InProgress)throw new InvalidOperationException("Only production in progress can be completed.");if(order.PlannedQuantity<0)throw new InvalidOperationException("Planned quantity cannot be negative.");if(actualQuantity<=0)throw new InvalidOperationException("Actual produced quantity must be greater than zero.");if(wastageQuantity<0)throw new InvalidOperationException("Wastage quantity cannot be negative.");if(actualQuantity+wastageQuantity>order.PlannedQuantity)throw new InvalidOperationException("Produced quantity plus wastage cannot exceed planned quantity.");if(!await db.InventoryTransactions.AnyAsync(x=>x.ReferenceType=="ProductionOrder"&&x.ReferenceId==id&&x.TransactionType==InventoryTransactionType.ProductionConsumption))throw new InvalidOperationException("Record material consumption before completing production.");if(await db.InventoryTransactions.AnyAsync(x=>x.ReferenceType=="ProductionOrder"&&x.ReferenceId==id&&x.TransactionType==InventoryTransactionType.ProductionOutput))throw new InvalidOperationException("Production output has already been posted.");db.InventoryTransactions.Add(new InventoryTransaction{ProductId=order.ProductId,WarehouseId=order.WarehouseId,TransactionType=InventoryTransactionType.ProductionOutput,Quantity=actualQuantity,UnitCost=order.MaterialCost/actualQuantity,ReferenceType="ProductionOrder",ReferenceId=id,TransactionDate=order.ProductionDate,Notes=notes,CreatedById=user.FindFirstValue(ClaimTypes.NameIdentifier)});order.ActualQuantity=actualQuantity;order.WastageQuantity=wastageQuantity;order.Notes=notes??order.Notes;order.Status=ProductionOrderStatus.Completed;order.CompletedAt=DateTime.UtcNow;order.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync(user,"Complete","ProductionOrder",id,$"Completed {order.Number}; output {actualQuantity}");await tx.CommitAsync();}
}
